import { ConfigurationError } from "@zudojs/errors";

function requireDatabaseUrl(env) {
  const url = env["DATABASE_URL"];
  if (!url) {
    throw new ConfigurationError("DATABASE_URL is not set");
  }
  if (!/^postgres(ql)?:\/\//.test(url)) {
    throw new ConfigurationError("DATABASE_URL must start with postgres://");
  }
  return url;
}

for (const env of [{}, { DATABASE_URL: "mysql://root:hunter2@db/tasks" }, { DATABASE_URL: "postgresql://db/tasks" }]) {
  try {
    console.log("ok:", requireDatabaseUrl(env));
  } catch (error) {
    if (error instanceof ConfigurationError) console.log(error.name, "-", error.message);
  }
}

