import { PGlite } from "@electric-sql/pglite";
import { createDatabaseClient, createMigrationRunner, noopDatabaseLogger } from "@zudojs/database";

const pg = new PGlite();
const raw = (db) => ({
  $queryRawUnsafe: async (sql, ...values) => (await db.query(sql, values)).rows,
  $executeRawUnsafe: async (sql, ...values) => (await db.query(sql, values)).affectedRows ?? 0,
});
const client = createDatabaseClient({
  prisma: { ...raw(pg), $connect: () => pg.waitReady, $disconnect: () => pg.close(),
    $transaction: (work) => pg.transaction((tx) => work(raw(tx))) },
  logger: noopDatabaseLogger,
});
await client.connect();

const runner = createMigrationRunner(client, [
  { version: 1, name: "create-tasks", up: (tx) => tx.$executeRawUnsafe("CREATE TABLE tasks (id serial PRIMARY KEY, title text NOT NULL)") },
  { version: 2, name: "add-done", up: (tx) => tx.$executeRawUnsafe("ALTER TABLE tasks ADD COLUMN done boolean NOT NULL DEFAULT false") },
]);
const first = await runner.migrate();
const again = await runner.migrate();
console.log(first.applied.length, again.applied.length, again.skipped.length);
await client.disconnect();

