const FIELDS = ["title", "done", "priority"];

function whereEquals(filter, fields) {
  const params = [];
  const parts = [];
  for (const [key, value] of Object.entries(filter)) {
    if (!fields.includes(key)) throw new TypeError("Unknown field");
    params.push(value);
    parts.push(`"${key}" = $${params.length}`);
  }
  return { sql: parts.join(" AND "), params };
}

console.log(whereEquals({ done: false, priority: "high" }, FIELDS));
try {
  whereEquals({ "1=1; --": 1 }, FIELDS);
} catch (error) {
  console.log(error.name, error.message);
}

