const SORTABLE = ["id", "title", "createdAt"];

function parseSort(text) {
  const desc = text.startsWith("-");
  const field = desc ? text.slice(1) : text;
  if (!SORTABLE.includes(field)) return { status: 400 };
  return { status: 200, sort: { field, direction: desc ? "desc" : "asc" } };
}

console.log(parseSort("title"));
