function updateSql(id, data) {
  const params = [];
  const sets = Object.entries(data)
    .filter(([, value]) => value !== undefined)
    .map(([field, value]) => `"${field}" = $${params.push(value)}`);
  const sql = `UPDATE tasks SET ${sets.join(", ")} WHERE "id" = $${params.push(id)}`;
  return { sql, params };
}

for (const { sql, params } of [
  updateSql(4, { done: true, title: undefined, priority: "high" }),
  updateSql(7, { title: "Pack bags" }),
]) {
  console.log(sql, params);
}

