const FIELDS = ["id", "title", "createdAt", "deletedAt"];

function column(field, fields) {
  if (!fields.includes(field)) {
    throw new TypeError(`Unknown field "${field}"`);
  }
  return `"${field.replace(/[A-Z]/g, (c) => "_" + c.toLowerCase())}"`;
}

